"""Build the project's single, explicitly synthetic career-feedback dataset.

Run from any directory with: python ml/src/build_synthetic_career_dataset.py
The records are structured examples for exploration, not authoritative local
qualification, licensing, vacancy, salary, or admissions data.
"""

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
OUTPUT = ROOT / "ml" / "data" / "synthetic" / "career_feedback_dataset.jsonl"


def pathway(id, sector, role, aliases, courses, interests, skills, activities,
            summary, entry_roles, preparation, projects, applications, interviews,
            cv, progression, verify):
    return {
        "record_id": id,
        "record_type": "career_pathway",
        "is_synthetic": True,
        "evidence_status": "illustrative_guidance_not_verified_local_requirements",
        "sector": sector,
        "occupation_title": role,
        "alternate_titles": aliases,
        "related_courses": courses,
        "requirements_and_qualification_notes": (
            "Illustrative study areas to explore: " + ", ".join(courses) +
            ". This synthetic record does not set formal admission grades, accredited-program lists, "
            "licensing, supervised-practice, or professional-registration requirements; verify those with current Kenyan authorities and institutions."
        ),
        "interest_signals": interests,
        "skills": skills,
        "preferred_activities": activities,
        "role_summary": summary,
        "entry_level_roles": entry_roles,
        "preparation_pathway": preparation,
        "portfolio_or_practice_ideas": projects,
        "application_channel_types": applications,
        "sample_interview_questions": interviews,
        "cv_tailoring_guidance": cv,
        "progression_options": progression,
        "local_verification_note": verify,
        "example_student_queries": [
            f"What should I study and practise to explore {role.lower()}?",
            f"How can I tailor my CV for an entry-level {role.lower()} opportunity?",
            f"What interview questions could help me prepare for {role.lower()} roles?",
        ],
        "retrieval_eval_queries": [
            f"Which course areas, skills, and projects can help me explore {role.lower()} in {sector.lower()}?",
            f"How do I prepare for an entry-level opportunity as a {role.lower()}?",
        ],
        "limitations": "Synthetic example for career exploration. It is not a live vacancy, guaranteed route, professional licensing rule, or verified Kenyan qualification requirement.",
    }


